-- PT122-S1-Q6. Batch 05.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch05$PT122-S1-Q6$batch05$ AND q.stimulus=$batch05$Patti: Most parents are eager for their preschoolers to learn as much as possible. However, instead of providing general opportunities for their children to learn, parents often direct their children’s learning to their own personal concerns. Because children have a natural curiosity and thirst for knowledge, they learn an enormous amount simply through growing and adapting to the world. Therefore, this type of directed learning is unlikely to improve a child’s preschool education.$batch05$ AND q.prompt=$batch05$Which one of the following is an assumption on which Patti's argument depends?$batch05$ AND q.correct_choice=$batch05$D$batch05$) THEN RAISE EXCEPTION 'Question changed: PT122-S1-Q6'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch05$PT122-S1-Q6$batch05$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT122-S1-Q6'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch05$PT122-S1-Q6$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch05$Conclusion$batch05$, $batch05$Directed learning is unlikely to improve a child's preschool education.$batch05$), (1, $batch05$Evidence$batch05$, $batch05$Children learn an enormous amount just by growing and adapting to the world.$batch05$), (2, $batch05$Evaluate$batch05$, $batch05$Patti says children learn plenty on their own, so the parents' steering adds nothing. But what if that steering is part of how children grow and adapt? Then it would be feeding the very learning Patti praises. The answer needs to keep directed learning separate from natural learning.$batch05$), (3, $batch05$Goal$batch05$, $batch05$A defender: directed learning is not a necessary part of growing and adapting to the world.$batch05$)) v(position,label,body) WHERE q.qid=$batch05$PT122-S1-Q6$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch05$A$batch05$, $batch05$Where parents got the idea for directed learning does not affect whether it helps.$batch05$), ($batch05$B$batch05$, $batch05$If children struggle to adapt without parental guidance, directed learning may be exactly what they need.$batch05$), ($batch05$C$batch05$, $batch05$This is the most popular wrong answer. It mentions the right things (directed learning, general opportunities), but it points the wrong way. If directed learning enhances learning opportunities, it would *improve* a child's education. Patti would never assume that.$batch05$), ($batch05$D$batch05$, $batch05$Negate it: "directed learning *is* a necessary part of growing and adapting." Then it is part of how children learn that enormous amount, and Patti cannot say it fails to help.$batch05$), ($batch05$E$batch05$, $batch05$Formal schooling comes after preschool. The argument is about preschoolers.$batch05$)) v(letter,body) WHERE q.qid=$batch05$PT122-S1-Q6$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
